        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        margin: 0 0 1rem;
        padding: 0.35rem 0.75rem;
        border-radius: 999px;
        background: #eff6ff;
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 600;
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(1.75rem, 4vw, 2.25rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 1.5rem;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      .checkbox-row {
        display: flex;
        gap: 0.75rem;
        align-items: flex-start;
        padding: 1rem;
        border: 1px solid var(--panel-border);
        border-radius: 1rem;
        background: #fbfdff;
      }

      input[type="checkbox"] {
        margin: 0.15rem 0 0;
        inline-size: 1.1rem;
        block-size: 1.1rem;
        accent-color: var(--accent);
      }

      label {
        font-weight: 600;
        line-height: 1.5;
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .required-note {
        color: var(--accent-strong);
      }

      button {
        border: 0;
        border-radius: 0.95rem;
        padding: 0.95rem 1.2rem;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 120ms ease, box-shadow 120ms ease;
        box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.35);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        font-size: 0.95rem;
        color: var(--accent-strong);
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.5rem;
        }

        .checkbox-row {
          padding: 0.9rem;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
          color: CanvasText;
        }

        .card,
        .checkbox-row {
          background: Canvas;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .eyebrow,
        button {
          background: ButtonFace;
          color: ButtonText;
          border: 1px solid ButtonBorder;
        }

        .helper-text,
        .intro,
        .status {
          color: CanvasText;
        }

        .skip-link:focus,
        button:focus-visible,
        input:focus-visible {
          outline-color: Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const createElement = (template) => {
        const wrapper = document.createElement("template");
        wrapper.innerHTML = template.trim();
        return wrapper.content.firstElementChild;
      };

      function ConsentField() {
        return createElement(`
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="terms"
                name="terms"
                type="checkbox"
                required
                aria-describedby="terms-help"
              />
              <div>
                <label for="terms">I agree to the Terms of Use <span class="required-note" aria-hidden="true">*</span></label>
                <p class="helper-text" id="terms-help">Required to continue with your submission.</p>
              </div>
            </div>
          </div>
        `);
      }

      function App() {
        const main = createElement(`
          <main id="main-content">
            <section class="card" aria-labelledby="page-title">
              <p class="eyebrow">Quick confirmation</p>
              <h1 id="page-title">Confirm your consent</h1>
              <p class="intro">Review and accept the terms to submit this form.</p>
              <form novalidate>
                <div data-field-slot></div>
                <button type="submit">Submit</button>
                <p class="status" aria-live="polite"></p>
              </form>
            </section>
          </main>
        `);

        const form = main.querySelector("form");
        const checkbox = ConsentField();
        const checkboxInput = checkbox.querySelector("#terms");
        const status = main.querySelector(".status");

        main.querySelector("[data-field-slot]").replaceWith(checkbox);

        form.addEventListener("submit", (event) => {
          if (!form.checkValidity()) {
            event.preventDefault();
            checkboxInput.focus();
            status.textContent = "Please agree to the Terms of Use before submitting.";
            return;
          }

          event.preventDefault();
          status.textContent = "Thanks — your consent has been recorded.";
        });

        checkboxInput.addEventListener("change", () => {
          if (checkboxInput.checked) {
            status.textContent = "";
          }
        });

        return main;
      }

      document.getElementById("app").appendChild(App());
    </script>
  </body>
</html>
